const { chromium } = require('/tmp/avb-g04EhM/project/node_modules/playwright');
(async () => {
  const b = await chromium.launch();
  for (const [name, w] of [['d',1280],['m',400]]) {
    const p = await b.newPage({ viewport: { width: w, height: 900 } });
    p.on('console', m => m.type()==='error' && console.log('ERR', m.text()));
    p.on('requestfailed', r => console.log('FAIL', r.url()));
    p.on('response', r => r.status()>=400 && console.log(r.status(), r.url()));
    for (const pg of ['index','products','pricing','orders','about','contact']) {
      await p.goto(`http://127.0.0.1:${process.env.PORT}/${pg}.html`);
      await p.screenshot({ path: `${process.env.TMPDIR}/shots/${pg}-${name}.png`, fullPage: true });
    }
  }
  await b.close();
})();
EOF
(node server.js >/dev/null 2>&1 &) ; sleep 1; node $TMPDIR/shot.js; ls $TMPDIR/shots

